#!/usr/bin/env python3
# Finary One : fiche publique, equipe et conditions d'acces
# Remplacement des blocs vides par des informations publiques sourcees.
import base64, hashlib, json, zlib
from pathlib import Path
PATCHES=json.loads(zlib.decompress(base64.b64decode('')))
ready=[]
for item in PATCHES:
    path=Path(item['path'])
    old=path.read_bytes()
    sha=hashlib.sha256(old).hexdigest()
    if sha==item['new']:continue
    if sha!=item['old']:raise SystemExit('Fichier modifie depuis preparation : '+str(path))
    new=old
    for start,end,replacement in reversed(item['changes']):
        new=new[:start]+base64.b64decode(replacement)+new[end:]
    assert hashlib.sha256(new).hexdigest()==item['new']
    ready.append((path,new))
for path,new in ready:path.write_bytes(new)
print(len(ready),'fichiers mis a jour')
